/** `enter`, variant Dungeon: Enters a dungeon instance: a new one for one key, or one that exists by `name`. */
export interface EnterRequestDungeon {
  /** Where to go. Dungeons: `crypt`, `winter_instance`, `spider_instance`, `tomb`. `dreams`: the Cave of Many Dreams. `duelland`: watch a duel. `dungeon0` and `cgallery` are for GMs only. It selects the variant. */
  place: "crypt" | "winter_instance" | "spider_instance" | "tomb";
  /** An instance that exists, to join it without a key. The instance must be of this `place`. Absent (or falsy): the server makes a new instance and uses one key. */
  name?: InstanceName;
}

/** `enter`, variant Duel: Watches a duel: moves you into its instance as a spectator. */
export interface EnterRequestDuel {
  /** Where to go. Dungeons: `crypt`, `winter_instance`, `spider_instance`, `tomb`. `dreams`: the Cave of Many Dreams. `duelland`: watch a duel. `dungeon0` and `cgallery` are for GMs only. It selects the variant. */
  place: "duelland";
  /** The instance of the duel. Without it, or with a name that is not a `duelland` instance, the reply is `cant_enter`. */
  name: InstanceName;
}

/** `enter`, variant GM: GMs only. Makes a solo instance of `dungeon0`, or of `cgallery` (a gallery with one NPC for each cosmetic). In `cgallery` already, you keep your position. */
export interface EnterRequestGM {
  /** Where to go. Dungeons: `crypt`, `winter_instance`, `spider_instance`, `tomb`. `dreams`: the Cave of Many Dreams. `duelland`: watch a duel. `dungeon0` and `cgallery` are for GMs only. It selects the variant. */
  place: "dungeon0" | "cgallery";
}

/** `enter`, variant Dreams: Opens a run of the Cave of Many Dreams for your party, or puts you back in your run after a disconnect. The handler returns at once; `enter_dreams` replies later. */
export interface EnterRequestDreams {
  /** Where to go. Dungeons: `crypt`, `winter_instance`, `spider_instance`, `tomb`. `dreams`: the Cave of Many Dreams. `duelland`: watch a duel. `dungeon0` and `cgallery` are for GMs only. It selects the variant. */
  place: "dreams";
  /** Must be absent. A truthy `name` fails with `cant_reenter`. */
  name?: InstanceName;
}

/** `enter`, variant Other: Any other value. The `resort` branch is dead code (`data.place == "resort" && 0`). */
export interface EnterRequestOther {
  /** Where to go. Dungeons: `crypt`, `winter_instance`, `spider_instance`, `tomb`. `dreams`: the Cave of Many Dreams. `duelland`: watch a duel. `dungeon0` and `cgallery` are for GMs only. It selects the variant. */
  place: string;
}

/** `enter`: the payload you send (one of the variants, by `place`). */
export type EnterRequest =
  | EnterRequestDungeon
  | EnterRequestDuel
  | EnterRequestGM
  | EnterRequestDreams
  | EnterRequestOther;

/** `enter` reply: All checks pass. A new dungeon instance has a random name of 24 characters, and the server uses one key. A `player` update follows, then a second one with `reopen` (the key is gone). */
