/** `enter` reply: After the move and the `game_log`. */
export interface EnterDuelSuccess extends Omit<GameResponseSuccess, "response" | "place" | "success"> {
  /** Always `"data"`. */
  response: "data";
  /** The request. */
  place: "enter";
  /** Always `true`. */
  success: true;
  [key: string]: unknown;
}

/** `enter` reply: Your `role` is `"gm"`. A `player` update follows. */
