/** `enter` reply: After the move (and, for `cgallery`, after the NPCs). */
export interface EnterGMSuccess extends Omit<GameResponseSuccess, "response" | "place" | "success"> {
  /** Always `"data"`. */
  response: "data";
  /** The request. */
  place: "enter";
  /** Always `true`. */
  success: true;
  [key: string]: unknown;
}

/** `enter` reply: All checks pass, later (the entry animation takes 1,800 ms, then database work). Your party is in the first floor of a new run, or you are back in your run after a disconnect (`resumed: true`). It comes after `new_map`. */
