/** `property`, variant Typing: `typing` is truthy. The server sets `s.typing` to `{ms: 4000}`. The call costs nothing when `s.typing` was absent or had less than 3,000 ms left. */
export interface PropertyRequestTyping {
  /** Selects the path. If truthy, the server gives you the `typing` condition for 4,000 ms and ignores `afk`. If falsy or absent, the server reads `afk`. */
  typing: true;
}

/** `property`, variant AFK: The server sets or clears `player.afk` from `afk`. */
export interface PropertyRequestAFK {
  /** Falsy or absent. */
  typing?: false;
  /** `true` sets `player.afk`. `false` clears it, but only if `player.afk` had a value before. */
  afk?: boolean;
}

/** `property`: the payload you send (one of the variants, by `typing`). */
export type PropertyRequest =
  | PropertyRequestTyping
  | PropertyRequestAFK;

/** `property` reply: Always. There is no `game_response`. */
export type PropertyTyping = PlayerEvent;

/** `property` reply: `player.afk` changed. There is no `game_response`. */
export type PropertyAFKChange = PlayerEvent;

/** `random_look` reply: Always, at once, also without a character. The first line of the handler returns; no other code of it runs. */
export type RandomLookHint = "socket.emit('enter',{place:'cgallery'})";

/** `render`: the payload you send. */
export interface RenderRequest {
  /** The admin secret of the server. */
  pass: string;
  /** JavaScript that the server runs with `eval`. It can set the local variables `output`, `json_output`, `window` and `after`, and it can read `player` (your character, or `undefined`). */
  code: string;
}

/** `render` reply: `code` set `window` (truthy). The official client copies `window` into its globals, then runs `after`. */
export interface RenderWindow {
  /** The value of `window`. */
  window: unknown;
  /** The value of `after` (default `""`). */
  after: string;
  /** `"for(var id in data.window) window[id]=data.window[id]; eval(data.after);"`. */
  code: string;
}

/** `render` reply: No `window`, and `code` set `json_output` to anything but `undefined`. */
export interface RenderJSON {
  /** The value of `output` (default `""`). */
  output: unknown;
  /** The value of `json_output`. */
  json_output: unknown;
  /** The code for the client. */
  code: "show_json(data.json_output)";
}

/** `render` reply: No `window` and no `json_output`. When `code` throws, `output` is `"Exception: "` plus the error. */
export interface RenderText {
  /** The value of `output` (default `""`). */
  output: unknown;
  /** `'show_modal("<pre>"+data.output+"</pre>")'`. */
  code: string;
}

/** `requested_ack`: the payload you send. */
export type RequestedAckRequest = unknown;

/** `respawn`: the payload you send. */
export interface RespawnRequest {
  /** If truthy, you come back in `woffice` (spawn 0), not at the death point of your map. @default false */
  safe?: boolean;
}

/** `respawn` reply: All checks pass. The server removes `block`, sets HP to the maximum and MP to half, and on a `hardcore` server resets the character (`reset_player`). Then it moves you with `effect: 1`: to `woffice` with `safe`, else to `G.maps[map].on_death`, else to the `on_death` of `main` (`["main", 5]`). A `player` update follows. */
export type RespawnMoved = NewMapData;

/** `respawn` reply: After the move, the party update and a second `player` update (`u+cid`). */
export interface RespawnSuccess extends Omit<GameResponseSuccess, "response" | "place" | "success"> {
  /** Always `"data"`. */
  response: "data";
  /** The request. */
  place: "respawn";
  /** Always `true`. */
  success: true;
  /** Tells the official client to fire its `respawn` code event. */
  cevent: "respawn";
  [key: string]: unknown;
}

/** `respawn` failure: No character, or your character is not dead (`rip` is falsy). */
export interface RespawnFailureInvalid {
  /** The code. */
  response: "invalid";
  /** The place. */
  place: "respawn";
  /** Always true. */
  failed: true;
}

/** `respawn` failure: You died in a map of the Cave of Many Dreams. The server offers a rescue in the cave (`cave_fallen`): a revival room, unless a vote runs. */
export interface RespawnFailureCaveRescuer {
  /** The code. */
  response: "cave_rescuer";
  /** The place. */
  place: "respawn";
  /** Always true. */
  failed: true;
}

