  /** Always `"data"`. */
  response: "data";
  /** The request. */
  place: "tavern";
  /** Always `true`. */
  success: true;
  /** Your `request_id`. */
  request_id: unknown;
  /** Always `"info"`. */
  event: "info";
  /** As in the `tavern` reply. */
  edge: number;
  /** As in the `tavern` reply. */
  max: number;
  /** Your `game`, when it is truthy. */
