/** `tracker` reply: You have a character with `player.tracker` set: your inventory holds a `tracker` or a `supercomputer`. */
export interface TrackerData {
  /** Your kills per monster type (`player.p.stats.monsters`). */
  monsters: Record<string, number>;
  /** Extra score per monster type: a kill of a monster worth more than 1 adds `score - 1` (node/server.js:2760, 2807). The tracker adds it to `monsters`. */
  monsters_diff: Record<string, number>;
  /** Your exchanges per item (`player.p.stats.exchanges`). */
  exchanges: Record<string, number>;
  /** The drop table of each map (`D.drops.maps`), with `global` and `global_static`. */
  maps: Record<string, DropRow[]>;
  /** Each table that a `[chance, "open", table]` row names, from every table in this payload. Also the exchange table of each exchangeable item: key `<item>`, or `<item><level>` for an item that you upgrade or compound. */
  tables: Record<string, DropRow[]>;
  /** `player.max_stats` of your account: `{monsters: {<type>: [kills, character name]}, level}`, the best character of the account for each monster type (node/server.js:11663-11675). */
  max: TrackerMax;
  /** The drop tables of monsters on their home server (`D.drops.monsters_home_server`), or `{}`. These are drop tables, not kill counts. */
  monsters_home_server: Record<string, DropRow[]>;
  /** The drop table of each monster type (`D.drops.monsters`). The code for a filtered list (only types with 100 kills) does not run: its condition is `player.computer || 1`. */
  drops: Record<string, DropRow[]>;
  /** The same object as `monsters_home_server`. */
  drops_home: Record<string, DropRow[]>;
  /** `D.drops.maps.global`: the table that every kill rolls. Present when the table exists (an empty array also counts). */
  global?: DropRow[];
  /** `D.drops.maps.global_static`, by the same rule. */
  global_static?: DropRow[];
}

/** `trade`, variant Show: Shows the trade slots: sets `player.p.trades = 1`. */
export interface TradeRequestShow {
  /** `"show"` sets `player.p.trades = 1`. `"hide"` sets it to `null`. Any other value does nothing and sends nothing (node/server.js:12576-12580). */
  event: "show";
}

/** `trade`, variant Hide: Hides the trade slots: sets `player.p.trades = null`. */
export interface TradeRequestHide {
  /** `"show"` sets `player.p.trades = 1`. `"hide"` sets it to `null`. Any other value does nothing and sends nothing (node/server.js:12576-12580). */
  event: "hide";
}

/** `trade`: the payload you send (one of the variants, by `event`). */
export type TradeRequest =
  | TradeRequestShow
