/** `transport`: the payload you send. */
export interface TransportRequest {
  /** The map to go to. In a map of the Cave of Many Dreams: the next floor, or `main` to leave the cave. */
  to: MapName;
  /** The spawn on the destination map. It must match the spawn of the door or the spawn of the Transporter list (`winterland` 1, `main` 9, `desertland` 1, `cyberland` 0). @default 0 */
  s?: number;
}

/** `transport` reply: A normal move: all checks pass. The server first lowers by 5,200 ms the time of each condition that is not a debuff and has less than 60,000 ms left (`decay_s`; a `citizens` aura also has its numbers divided by 4). A `player` update follows. */
export type TransportMoved = NewMapData;

/** `transport` reply: A normal move, after `new_map` and `player`. */
export interface TransportSuccess extends Omit<GameResponseSuccess, "response" | "place" | "success"> {
  /** Always `"data"`. */
  response: "data";
  /** The request. */
  place: "transport";
  /** Always `true`. */
  success: true;
  [key: string]: unknown;
}

/** `transport` reply: Bank entry: the destination has `mount` and you are not in a bank. Bank exit: you are in a bank and the destination has no `mount`. The server adds 32 call-cost (entry) or 16 (exit) and starts a database transaction; the move comes later. For a `ulocked` bank map entered from outside the bank, this reply comes after a database read of the unlock flag. */
export interface TransportBankPending extends Omit<GameResponseSuccess, "response" | "place" | "success"> {
  /** Always `"data"`. */
  response: "data";
  /** The request. */
  place: "transport";
  /** Always `false`: the move did not happen yet. */
  success: false;
  /** The bank transaction runs. */
  in_progress: true;
  [key: string]: unknown;
}

/** `transport` reply: Later: the bank transaction succeeded. Then two `player` updates follow: one from the move, then a full one (`resend(player)`). After an entry, the second has `user`: your bank packs `items0` to `items47`, `gold`, `rewards`, `unlocked`. */
export type TransportBankDone = NewMapData;

/** `transport` reply: You are in a map of the Cave of Many Dreams (checked after `transport_failed`). A different handler, `generated_use_door`, does the move; it is asynchronous. `map` is the new floor. A door to `main` leaves the cave: you get `cave` `{type: "ended", reason: "exit"}`, `new_map` and `player` first, and the reply has `exited: true` in place of `map`. */
export interface TransportCaveDoor extends Omit<GameResponseSuccess, "response" | "place" | "success"> {
  /** Always `"data"`. */
  response: "data";
  /** The request. */
  place: "transport";
  /** Always `true`. */
  success: true;
  /** The floor that you moved to. */
  map?: MapName;
  /** You left the cave through a door to `main`. */
  exited?: true;
  [key: string]: unknown;
}

/** `transport` failure: You cannot walk (`can_walk`: dead, `stunned`, `fingered`, `stoned`, `deepfreezed`, `sleeping`, or `dash`), or you are in `jail`. */
export interface TransportFailureTransportFailed {
  /** The code. */
  response: "transport_failed";
  /** The place. */
  place: "transport";
  /** Always true. */
  failed: true;
}

/** `transport` failure: Cave map: the door failed. `reason` is the message of the error. `use_exit`: you cannot walk or are dead, or `to` is not a floor of the run. `cave_closed`: the run ended or you left it. `cave_paused`: a conversation pauses the run. `transport_cant_reach`: no door to `to` with spawn `s` is near you. `seal_closed`: the current floor is not complete. `transport_failed`: the move failed after the server built the floor. Another error gives its own message. */
export interface TransportFailureData {
  /** The code. */
  response: "data";
  /** The place. */
  place: "transport";
  /** Always true. */
  failed: true;
  /** The message of the error. */
  reason: string;
}

/** `transport` failure: `to` is not a map, it has no instance, its instance does not allow entry (`allow`), or it is a cave map (`generated_can_enter`). */
export interface TransportFailureCantEnter {
  /** The code. */
  response: "cant_enter";
  /** The place. */
  place: "transport";
  /** Always true. */
  failed: true;
}

/** `transport` failure: More than 5 monsters target you. */
export interface TransportFailureCantEscape {
  /** The code. */
  response: "cant_escape";
  /** The place. */
  place: "transport";
  /** Always true. */
  failed: true;
}

/** `transport` failure: You use the Transporter (or you are a GM, or in `woffice` on a `hardcore` server) and you have the `dampened` condition. */
export interface TransportFailureTransportCantDampened {
  /** The code. */
  response: "transport_cant_dampened";
  /** The place. */
  place: "transport";
  /** Always true. */
  failed: true;
}

/** `transport` failure: No door to `to` with spawn `s` is within `B.door_dist` (112 px) of you. And no Transporter of your map within `B.transporter_dist` (160 px) lists `to` with spawn `s`. GMs, and characters in `woffice` on a `hardcore` server, skip this check. */
export interface TransportFailureTransportCantReach {
  /** The code. */
  response: "transport_cant_reach";
  /** The place. */
  place: "transport";
  /** Always true. */
  failed: true;
}

/** `transport` failure: The door is `protected`, and a gatekeeper monster is alive in your instance. */
export interface TransportFailureTransportCantProtection {
  /** The code. */
  response: "transport_cant_protection";
  /** The place. */
  place: "transport";
  /** Always true. */
  failed: true;
}

/** `transport` failure: You are in a bank (`player.user`), the door is `ulocked` into a bank map, and your account did not unlock that map. */
export interface TransportFailureTransportCantLocked {
  /** The code. */
  response: "transport_cant_locked";
  /** The place. */
  place: "transport";
  /** Always true. */
  failed: true;
}

/** `transport` failure: Bank entry or exit: a bank entry or exit of this character runs already. */
export interface TransportFailureBankOpi {
  /** The code. */
  response: "bank_opi";
  /** The place. */
  place: "transport";
  /** Always true. */
  failed: true;
}

/** `transport` failure: Later: the bank entry transaction failed. You stay where you are. The object has no `place` and no `failed`. */
export interface TransportFailureBankOpx {
  /** The code. */
  response: "bank_opx";
  /** Only for `already_in_bank`: the id of the character that holds the bank now (`owner.mounted_to`). `null` if the account record is missing (`owner && owner.mounted_to`). */
  name?: string | null;
  /** `character_gone`: the session of your character changed. `already_in_bank`: another character of the account (or another server) has the bank. `exception`: a database error, after up to 6 tries. */
  reason: "character_gone" | "already_in_bank" | "exception";
}

/** `transport`: every failure reply on `game_response`, in check order. */
export type TransportFailure =
  | TransportFailureTransportFailed
  | TransportFailureData
  | TransportFailureCantEnter
  | TransportFailureCantEscape
  | TransportFailureTransportCantDampened
  | TransportFailureTransportCantReach
  | TransportFailureTransportCantProtection
  | TransportFailureTransportCantLocked
  | TransportFailureBankOpi
  | TransportFailureBankOpx;

/** `unequip`: the payload you send. */
export interface UnequipRequest {
  /** A key of `slots`: an equipment slot (`"mainhand"`, `"ring1"`, ...) or a trade slot (`"trade1"` to `"trade48"`). */
  slot: string;
}

/** `unequip` reply: All checks pass. The server empties the slot, stops your channeled actions (`c`) and adds the item to the inventory. A wishlist entry (flag `b`) is deleted and adds nothing. */
export interface UnequipSuccess extends Omit<GameResponseSuccess, "response" | "place" | "success"> {
  /** Always `"data"`. */
  response: "data";
  /** The request. */
  place: "unequip";
  /** Always `true`. */
  success: true;
  [key: string]: unknown;
}

/** `unequip` failure: No character, `slot` is missing or falsy, or the slot is empty. */
export interface UnequipFailureInvalid {
  /** The code. */
  response: "invalid";
  /** The place. */
  place: "unequip";
  /** Always true. */
  failed: true;
}

/** `unequip` failure: `slot` is `"elixir"`. */
export interface UnequipFailureCant {
  /** The code. */
  response: "cant";
  /** The place. */
  place: "unequip";
  /** Always true. */
  failed: true;
}

/** `unequip` failure: `slot` is a trade slot, and its item has `giveaway`. */
export interface UnequipFailureGiveaway {
  /** The code. */
  response: "giveaway";
  /** The place. */
  place: "unequip";
  /** Always true. */
  failed: true;
}

/** `unequip` failure: No empty inventory slot (`esize <= 0`), and the item is not a wishlist entry (`b`). */
export interface UnequipFailureNoSpace {
  /** The code. */
  response: "no_space";
  /** The place. */
  place: "unequip";
  /** Always true. */
  failed: true;
}

/** `unequip`: every failure reply on `game_response`, in check order. */
export type UnequipFailure =
  | UnequipFailureInvalid
  | UnequipFailureCant
  | UnequipFailureGiveaway
  | UnequipFailureNoSpace;

/** `upgrade`, variant Calculate: Only computes the chance of success. The server consumes nothing and starts no timer. */
export interface UpgradeRequestCalculate {
  /** The slot of the item to upgrade. */
  item_num: InventoryIndex;
  /** The slot of a `uscroll` (level + 1) or a `pscroll` (a stat). Required when there is no `offering_num`. */
  scroll_num?: InventoryIndex;
  /** The slot of an offering: an item of type `offering`, or an item with an `offering` property (an ingot or a nugget, only for an item at level 0). */
  offering_num?: InventoryIndex;
  /** The level of the item now. If it does not match, the upgrade fails. This stops a second upgrade on a slot that changed. */
  clevel: number;
  /** Selects the variant. If truthy, the server only sends the chance after the checks. It consumes nothing and starts no timer. @default false */
  calculate: true;
}

/** `upgrade`, variant Upgrade: Consumes the scroll and the offering and starts the upgrade timer. */
export interface UpgradeRequestUpgrade {
  /** The slot of the item to upgrade. */
  item_num: InventoryIndex;
  /** The slot of a `uscroll` (level + 1) or a `pscroll` (a stat). Required when there is no `offering_num`. */
  scroll_num?: InventoryIndex;
  /** The slot of an offering: an item of type `offering`, or an item with an `offering` property (an ingot or a nugget, only for an item at level 0). */
  offering_num?: InventoryIndex;
  /** The level of the item now. If it does not match, the upgrade fails. This stops a second upgrade on a slot that changed. */
  clevel: number;
  /** Falsy or absent. */
  calculate?: false;
}

/** `upgrade`: the payload you send (one of the variants, by `calculate`). */
export type UpgradeRequest =
  | UpgradeRequestCalculate
  | UpgradeRequestUpgrade;

/** `upgrade` reply: All checks pass. */
export interface UpgradeChance extends Omit<GameResponseSuccess, "response" | "place" | "success"> {
  /** The code. */
  response: "upgrade_chance";
  /** The request. */
  place: "upgrade";
  /** Always `true`. */
  success: true;
  /** Always `true`. */
  calculate: true;
  /** The chance of success, 0 to 1. A `pscroll` gives 0.99999; a grace offering without a scroll gives 1. */
  chance: number;
  /** The item. */
  item: ItemInstance;
  /** The grace of the item now (`item.grace || 0`). `ItemInstance` does not carry grace. */
  grace: number;
  /** The scroll, when the request has one. */
  scroll?: ItemName;
  /** The offering, when the request has one. */
  offering?: ItemName;
  [key: string]: unknown;
}

/** `upgrade` reply: All checks pass. There is no `game_response` now. */
export type UpgradeStarted = PlayerEvent;

/** `upgrade` reply: During the timer, each time the server shows one more digit of the roll, and once near the end with `p.success` or `p.failure`. Up to 5 times. */
export interface UpgradeProgress {
  /** All your timers (`player.q`). */
  q: Record<string, QueueEntry>;
  /** The slot of the placeholder. */
  num: InventoryIndex;
  /** The placeholder state, with the digits so far. */
  p: PlaceholderState;
}

/** `upgrade` reply: The timer ends and the roll succeeds. The slot gets the item back with its new level (or new `stat_type`, grace, or `p: "shiny"`). */
export interface UpgradeSuccess {
  /** The code. */
  response: "upgrade_success";
  /** The old level + 1. **Server bug:** the value is the same for a `pscroll` and a grace offering, which do not change the level. */
  level: number;
  /** The slot of the item. */
  num: InventoryIndex;
  /** You left the game during the timer. */
  stale?: true;
}

/** `upgrade` reply: A `pscroll` upgrade succeeds. */
export interface UpgradeStatSuccess {
  /** The code. */
  response: "upgrade_success_stat";
  /** The new stat of the item, from `G.items[scroll].stat`. */
  stat_type: string;
  /** The slot of the item. */
  num: InventoryIndex;
  /** You left the game during the timer. */
  stale?: true;
}

/** `upgrade` reply: An offering without a scroll added grace to the item. */
export interface UpgradeOfferingSuccess {
  /** The code. */
  response: "upgrade_offering_success";
  /** You left the game during the timer. */
  stale?: true;
}

/** `upgrade` reply: The timer ends and the roll fails. The item is gone, and the slot is `null`. Exceptions: a failed shiny attempt or a failure with `scroll4` (grade 3.6) puts the item back unchanged. */
export interface UpgradeFail {
  /** The code. */
  response: "upgrade_fail";
  /** The level that the upgrade tried: old level + 1. */
  level: number;
  /** The slot of the item. */
  num: InventoryIndex;
  /** You left the game during the timer. */
  stale?: true;
}

/** `upgrade` failure: No character. The handler reads `player.items` before it checks `player`, and the error goes to the `catch`. */
export interface UpgradeFailureException {
  /** The code. */
  response: "exception";
  /** The place. */
  place: "upgrade";
  /** Always true. */
  failed: true;
}

/** `upgrade` failure: The character is in the bank. */
export interface UpgradeFailureCantInBank {
  /** The code. */
  response: "cant_in_bank";
  /** The place. */
  place: "upgrade";
  /** Always true. */
  failed: true;
}

/** `upgrade` failure: You are not on `main`, or you are more than `B.sell_dist` (400 px) from the upgrade NPC. A character with a `computer` passes this check. */
export interface UpgradeFailureDistance {
  /** The code. */
  response: "distance";
  /** The place. */
  place: "upgrade";
  /** Always true. */
  failed: true;
}

/** `upgrade` failure: A `uscroll` on an item at grade 4. */
export interface UpgradeFailureMaxLevel {
  /** The code. */
  response: "max_level";
  /** The place. */
  place: "upgrade";
  /** Always true. */
  failed: true;
  /** The level of the item. */
  level: number;
}

/** `upgrade` failure: A `uscroll`, and the item is locked (`l`). */
export interface UpgradeFailureItemLocked {
  /** The code. */
  response: "item_locked";
  /** The place. */
  place: "upgrade";
  /** Always true. */
  failed: true;
}

/** `upgrade` failure: A `pscroll` stack smaller than `[1, 10, 100, 1000, 9999, 9999, 9999][grade]`. */
export interface UpgradeFailureUpgradeScrollQ {
  /** The code. */
  response: "upgrade_scroll_q";
  /** The scrolls needed. */
  q: number;
  /** The scrolls you have in that slot. */
  h: number;
}

/** `upgrade`: every failure reply on `game_response`, in check order. */
export type UpgradeFailure =
  | UpgradeFailureException
  | UpgradeFailureCantInBank
  | "upgrade_in_progress"
  | UpgradeFailureDistance
  | "upgrade_no_item"
  | "upgrade_invalid_offering"
  | "upgrade_no_scroll"
  | "upgrade_mismatch"
  | "upgrade_cant"
  | UpgradeFailureMaxLevel
  | "upgrade_incompatible_scroll"
  | UpgradeFailureItemLocked
  | UpgradeFailureUpgradeScrollQ;

/** `ureward`: the payload you send. */
export interface UrewardRequest {
  /** The account reward. Only `"c0"` exists: the reward for the tutorial, one roll on the `cosmo0` cosmetics table. */
  name: "c0";
}

/** `ureward` reply: The claim succeeded. `exchange` rolls `cosmo0` and adds the cosmetic to your account. It comes before the `player` update. */
export interface UrewardCosmetic {
  /** The code. */
  response: "cx_new";
  /** All your cosmetics with their counts (`player.p.acx`). */
  acx: Record<string, number>;
  /** The new cosmetic. */
  name: string;
  /** The table that gave it. */
  from: "cosmo0";
  /** `true` when the roll gave a bundle (`cxbundle`) and `name` is the bundle. `cosmo0` has two: `pinkb` and `blackw` (G.drops.cosmo0). */
  bundle: boolean;
}

/** `ureward` reply: The claim succeeded, after the `player` update. The claim is asynchronous: it comes after a database transaction. */
export interface UrewardSuccess {
  /** The code. The object has no `place` and no `success`. */
  response: "reward_received";
  /** All the reward names that the account claimed. */
  rewards: string[];
}

/** `ureward` failure: Transaction: the account did not finish the tutorial (no user data, or the tutorial is not complete up to its last lesson). */
export interface UrewardFailureRewardUnavailable {
  /** The code. */
  response: "reward_unavailable";
  /** Why. */
  reason: "tutorial_incomplete";
}

/** `ureward` failure: The database transaction failed for another reason. */
export interface UrewardFailureRewardUnavailable2 {
  /** The code. */
  response: "reward_unavailable";
  /** The reason from `tx` (common:mongodb_functions.js:95). */
  reason: "exception";
}

/** `ureward` failure: Your character left, or the socket now has another account, when the transaction ends. */
export interface UrewardFailureRewardUnavailable3 {
  /** The code. */
  response: "reward_unavailable";
  /** Why. */
  reason: "character_gone";
}

/** `ureward` failure: Any other error in the claim. */
export interface UrewardFailureRewardUnavailable4 {
  /** The code. */
  response: "reward_unavailable";
  /** Why. */
  reason: "server_error";
}

/** `ureward`: every failure reply on `game_response`, in check order. */
export type UrewardFailure =
  | "reward_notverified"
  | UrewardFailureRewardUnavailable
  | "reward_already"
  | UrewardFailureRewardUnavailable2
  | UrewardFailureRewardUnavailable3
  | UrewardFailureRewardUnavailable4;

/** `use`, variant Potion: Restores `G.skills.regen_hp.output` HP or `G.skills.regen_mp.output` MP, up to the maximum, and starts the potion cooldown of 4,000 ms. */
export interface UseRequestPotion {
  /** The regeneration to use. Selects the variant. */
  item: "hp" | "mp";
}

/** `use`, variant Other: Any other value, or no `item`. The server changes nothing, starts no cooldown, and sends only the success reply. */
export interface UseRequestOther {
  /** Any value but `"hp"` and `"mp"`, or absent. */
  item?: unknown;
}

/** `use`: the payload you send (one of the variants, by `item`). */
export type UseRequest =
  | UseRequestPotion
  | UseRequestOther;

/** `use` reply: Always when you have a character and the checks of the variant pass. */
export interface UseSuccess extends Omit<GameResponseSuccess, "response" | "place" | "success"> {
  /** Always `"data"`. */
  response: "data";
  /** The request. */
  place: "use";
  /** Always `true`. */
  success: true;
  /** The `item` from the request, unchanged. Absent when the request has no `item`. */
  used?: unknown;
  [key: string]: unknown;
}

/** `use` failure: The potion cooldown is active. `equip` of a potion uses the same cooldown (node/server.js:7825-7828, 7874). */
export interface UseFailureNotReady {
  /** The code. */
  response: "not_ready";
  /** The place. */
  place: "use";
  /** Always true. */
  failed: true;
  /** The time left on the potion cooldown. */
  ms: Milliseconds;
}

/** `use`: every failure reply on `game_response`, in check order. */
export type UseFailure =
  | UseFailureNotReady;

/** `achievement_progress`: the payload you receive. */
export interface AchievementProgressEvent {
  /** The achievement: a key of `G.achievements` with a `count`. */
  name: "abtesting" | "firehazard" | "stomped" | "gooped" | "festive";
  /** The count now (`item.acc`). For `festive` (damage) and `gooped` (attack values) it is a sum, so it can have a fraction. */
  count: number;
  /** The count that completes it: `G.achievements[name].count`. */
  needed: number;
}

/** `achievement_success`: the payload you receive. */
export interface AchievementSuccessEvent {
  /** The achievement. Each name except `"unlucky"` is a key of `G.achievements`. */
  name: "abtesting" | "firehazard" | "stomped" | "gooped" | "festive" | "lucky" | "unlucky";
}

/** `action`: the payload you receive. */
export interface ActionEvent extends Action {
}

/** `blocker`: the payload you receive. */
export interface BlockerEvent {
  /** The blocker. Only `"pvp"` exists. */
  type: "pvp";
  /** The `arena` instance lets players in (`instances.arena.allow`). Absent otherwise. */
  allow?: 1;
}

/** `cave`: the payload you receive. */
export type CaveEvent = CaveUpdate | CaveCueUpdate | CaveChatUpdate | CaveEnded;

/** `ccreport`: the payload you receive. */
export interface CcreportEvent {
  /** `socket.calls`: the calls of the last 4 s, oldest first. The sum of the costs is the call cost now (node/server_functions.js:5354-5361). */
  calls: CallLogEntry[];
  /** `limits.calls`, 200 (node/server.js:257). Caution: a socket without a character has a limit of 50, not this value (node/server.js:4905-4906). */
  climit: number;
  /** `socket.total_calls`: the number of events that this socket sent since it connected. */
  total: number;
}

/** `chat_log`: the payload you receive. */
export type ChatLogEvent = ChatLogPlayer | ChatLogNpc;

/** `chest_opened`: the payload you receive. */
export type ChestOpenedEvent = ChestOpenedResult | ChestOpenedGone;

/** `citizen`: the payload you receive. */
export type CitizenEvent = CitizenRepair | CitizenLamp | CitizenRouteMarks | CitizenDealerShuffle | CitizenDealerSay | CitizenDealerMock | CitizenDealerFlourish | CitizenDealerEmote;

/** `cm`: the payload you receive. */
export interface CmEvent {
  /** The name of the sender. */
  name: CharacterName;
  /** The `message` of the request, unchanged: any JSON value. A falsy value (absent, `null`, `0`, `false`, `""`) becomes `""` (node/server.js:5086). */
  message: unknown;
}

/** `code_eval`: the payload you receive. */
export type CodeEvalEvent = unknown;

/** `correction`: the payload you receive. */
export interface CorrectionEvent {
  /** The position of the character on the server. */
  x: number;
  /** The position of the character on the server. */
  y: number;
}

/** `death`: the payload you receive. */
export interface DeathEvent {
  /** The monster id. */
  id: string;
  /** The luck multiplier of the character that the monster targeted, or 1 when it had no target. */
  luckm: number;
  /** Only for a cooperative monster: the contribution points, keyed by character name (node/server.js:13315). */
  points?: Record<string, number>;
}

/** `dice`: the payload you receive. */
export type DiceEvent = DiceRoll | DiceLock | DiceBets;

/** `disappear`: the payload you receive. */
export type DisappearEvent = DisappearOutside | DisappearTransport | DisappearMagiport | DisappearInvis | DisappearReason | DisappearNotThere | DisappearRemoval | DisappearBare;

/** `disappearing_text`: the payload you receive. */
export type DisappearingTextEvent = DisappearingTextHelper | DisappearingTextDirect;

/** `disconnect_reason`: the payload you receive. */
export type DisconnectReasonEvent = "limitdc" | "limits" | "blocked" | string;

/** `drop`: the payload you receive. */
export interface DropEvent {
  /** The chest id: 30 random characters (`randomStr(30)`). Send it with `open_chest`. */
  id: string;
  /** The x position of the chest. */
  x: number;
  /** The y position of the chest. A PvP chest is 10 below the dead character. */
  y: number;
  /** The map of the chest. */
  map: MapName;
  /** The sprite of the chest. `drop_something`: `"chest3"`, `"chest4"` (gold x10), `"chest5"` (gold x50) or `"chest6"` (items). `"chest8"`: PvP or hardcore loot. `"chestp"`: an `essenceoflife`. `"cavechest"`: a cave chest. Default `"chest1"`. */
  chest: string;
  /** The number of item stacks in the chest. A PvP chest counts its PvP items (`pvp_items`). */
  items: number;
  /** The account ids (`owner`) that can open the chest: one per account in the party. Absent only on a cave chest that a run member did not make (`cave_send_chest`). */
  owners?: string[];
  /** The party name (the name of the leader). Only on a party chest. */
  party?: CharacterName;
}

/** `duel`: the payload you receive. */
export interface DuelEvent {
  /** Always `"chellenge"`. The server spells it this way. */
  event: "chellenge";
  /** The character that sent the challenge. */
  name: CharacterName;
}

/** `emote`: the payload you receive. */
export interface EmoteEvent {
  /** The emote: `G.skills[skill].emote`. In G it is the same as the skill name, for example `"wiggle"`. */
  name: string;
  /** The character that used the emote. */
  player: CharacterName;
  /** The target character. Absent when the emote has no target (node/server.js:10079). */
  target?: CharacterName;
  /** A random variation of the animation. */
  variation: 0 | 1 | 2;
}

/** `entities`: the payload you receive. */
export interface EntitiesEvent extends EntitiesFrame {
}

/** `eval`: the payload you receive. */
export type EvalEvent = EvalCode | string;

/** `friend`: the payload you receive. */
export type FriendEvent = FriendRequest | FriendNew | FriendLost;

/** `game_chat`: the payload you receive. */
export interface GameChatEvent extends LocalizedText {
  /** Only on duel results: `"#47C1AE"`. */
  color?: string;
  [key: string]: unknown;
}

/** `game_error`: the payload you receive. */
export type GameErrorEvent = "ERROR!" | GameErrorText;

/** `game_event`: the payload you receive. */
export interface GameEventEvent {
  /** The monster type of the boss that spawned. It is a key of `G.monsters`. */
  name: "pinkgoo" | "crabxx" | "snowman" | "dragold" | "franky" | "icegolem" | "mrpumpkin" | "mrgreen" | "grinch" | "slenderman" | "wabbit";
  /** The map of the boss. */
  map: MapName;
  /** A map position for the event. Absent for `pinkgoo`, `crabxx`, `slenderman` and `wabbit`. It is the top-left corner of the spawn area, except for `snowman` and `dragold`: both always send `900, -800`. */
  x?: number;
  /** Sent together with `x`. */
  y?: number;
}

/** `game_log`: the payload you receive. */
