/** `merrit_status`: the payload you receive. */
export type MerritStatusEvent = MerritStatus | MerritStatusError;

/** `new_map`: the payload you receive. */
export interface NewMapEvent extends NewMapData {
}

/** `notice`: the payload you receive. */
export interface NoticeEvent {
  /** The English text. From the admin `notice` handler: the `message` of the request, with no check of its type. */
  message: string;
  /** The phrase key. Absent on an admin notice. */
  phrase?: string;
  /** The values for the phrase. Absent on an admin notice. */
  phrase_args?: Record<string, unknown>;
}

/** `observer_broadcast`: the payload you receive. */
export interface ObserverBroadcastEvent {
  /** The group that the camera shows: `"party:<leader>"`, `"solo:<name>"`, `"town:<map>"`, or `null` when there is no group. */
  group: string | null;
  /** The members of the group, up to 10, keyed by name. It is `{}` for a town group or no group. */
  party: Record<string, PlayerSummary>;
  /** The members in the camera frame. Each is in the instance of the anchor character, 230 px or less in `x` and 125 px or less in `y` from it. */
  focus: CharacterName[];
  /** The map of the camera: the map of the anchor character, or the town map. */
  map: MapName;
  /** The camera position: the center of the `focus` characters, or the town point when `focus` is empty. */
  x: number;
  /** The camera position. */
  y: number;
  /** The characters online on this server, without NPCs and disconnected characters. */
  online: number;
  /** The time until the camera can change group. The group changes at each 30 s boundary of the server clock. */
  remaining_ms: Milliseconds;
  /** `"group"`: the camera follows a character. `"town"`: the town square shot. `"waiting"`: there is nothing to show. */
  kind: "group" | "town" | "waiting";
  /** `false` only when `kind` is `"waiting"`. Then the camera does not move. */
  available: boolean;
  /** The living characters in the town square shot. The town shot needs 6 or more. */
  town_players: number;
}

/** `online`: the payload you receive. */
export interface OnlineEvent {
  /** The character of a friend that logged in. */
  name: CharacterName;
  /** The server of that character: the region and the server name, for example `"EU I"` or `"US PVP"`. */
  server: string;
}

/** `party_update`: the payload you receive. */
export type PartyUpdateEvent = PartyUpdateState | PartyUpdateJoined | PartyUpdateLeft | PartyUpdateNone;

/** `partym`: the payload you receive. */
export interface PartymEvent {
  /** The name of the sender. */
  owner: CharacterName;
  /** The text, at most 1,200 characters. The server removes some characters first (`strip_string`). */
  message: string;
  /** The id of the sender: the character name. */
  id: CharacterName;
  /** Always `true`. */
  p: true;
}

/** `ping_ack`: the payload you receive. */
export interface PingAckEvent {
  /** The `id` that `ping_trig` sent. The official client sends a random string of 5 characters (js/functions.js:230-235). */
  id?: unknown;
  /** The `ui` that `ping_trig` sent. The official client sends `true` when it shows the ping in the log. */
  ui?: unknown;
  [key: string]: unknown;
}

/** `player`: the payload you receive. */
export interface PlayerEvent extends Character {
  /** Only from `resend` with `reopen`: items, gold or slots changed, so open windows must refresh. */
  reopen?: true;
  /** Only from `resend`: events that waited for this update, in order. Handle each `[event, payload]` as if the server sent it now. The list is not sent again. Not all of them answer a request: a `game_response` `condition` from `add_condition` can come at any time (a skill of another character, a monster, the anniversary event). */
  hitchhikers?: Hitchhiker[];
}

/** `players`: the payload you receive. */
export type PlayersEvent = PlayersEntry[] | Record<string, unknown>[];

/** `pm`: the payload you receive. */
export type PmEvent = PmMessage | PmDeliveryFailed;

/** `poke`: the payload you receive. */
export interface PokeEvent {
  /** The `name` of the request, unchanged. The server does not check it, so it can be any value, also a name that is not in view. Absent when the request has no `name` (the value is `undefined`, which JSON leaves out). */
  name?: unknown;
  /** The strength, from the level of the `poker` gloves: 1 below +8, 2 at +8, 3 at +9, 4 at +10 and more. */
  level: 1 | 2 | 3 | 4;
  /** The character that poked. */
  who: CharacterName;
}

/** `poker`: the payload you receive. */
export type PokerEvent = PokerState | PokerCards;

/** `pvp_list`: the payload you receive. */
export interface PvpListEvent {
  /** A copy of `code` from the request (`data && data.code`). Absent when the request has no `code`, `null` when the request data is `null`. */
  code?: unknown;
  /** Up to 200 PvP kills on this server since it started, newest first. */
  list: PvpListKill[];
}

/** `q_data`: the payload you receive. */
export interface QDataEvent {
  /** All timers of the character (`player.q`), not only the one that changed. The loop lowers `ms` one timer at a time (node/server.js:14735-14738), so the `ms` of this timer and of the timers before it in `q` is lower by this tick, and the `ms` of the timers after it is not yet. */
  q: QDataQueue;
  /** The slot of the placeholder: `num` of the timer. It is the slot value from the `upgrade` or `compound` request with no conversion, so it can be a numeric string. */
  num: InventoryIndex;
  /** The `p` of the placeholder item in that slot (node/server.js:14741). The server changes this same object on each tick: it adds one digit to `nums`, or sets `success` or `failure`. */
  p: PlaceholderState;
}

/** `reloaded`: the payload you receive. */
export interface ReloadedEvent {
  /** A text from the admin that describes the change, for example `"cx"`. It is `""` when the admin gives none. */
  change: string;
}

/** `request`: the payload you receive. */
export interface RequestEvent {
  /** The character that asks to join your party. To accept, send `party` with `event: "raccept"` and this name. */
  name: CharacterName;
}

/** `secondhands`: the payload you receive. */
export type SecondhandsEvent = ResaleItem[];

/** `server_info`: the payload you receive. */
export type ServerInfoEvent = ServerInfoState;

/** `server_message`: the payload you receive. */
export interface ServerMessageEvent extends LocalizedText {
  /** A CSS color, or `G.monsters[type].announce` for a boss. That is `true`, not a color, for `icegolem` in the current G (node/server.js:13627, 13633). */
  color: string | true;
  /** The kind of an item or gold announcement: found, received, gold from a chest, upgrade success or failure, compound success or failure. */
  type?: "server_found" | "server_received" | "server_gold" | "server_usuccess" | "server_ufail" | "server_csuccess" | "server_cfail";
  /** With `type`: the character of the announcement. */
  name?: CharacterName;
  /** With an item `type`: the item, as `cache_item` gives it. */
  item?: ItemInstance;
  /** Only with `type: "server_found"` from `add_shells`: the shells found (node/server.js:4824). */
  shells?: number;
  /** An event message: an event item, or the call to fight a cooperative boss. The server does not copy it to Discord. */
  event?: true;
  /** Only on a boss spawn: the format of the Discord copy (node/server.js:13627). `broadcast` also knows `"red"`; no call site sends it. */
  discord?: "orange";
  /** Only on the shutdown countdown: no Discord copy (node/server.js:16974). */
  nod?: true;
  /** Only on the shutdown countdown. The server does not read it; the meaning is unclear from the source. */
  log?: true;
  /** Only from `realm_broadcast`: the origin server, `region + " " + server_name`, for example `"EU I"` (node/server_functions.js:3490). */
  sname?: string;
  [key: string]: unknown;
}

/** `simple_eval`: the payload you receive. */
export type SimpleEvalEvent = SimpleEvalWindow | SimpleEvalJson | SimpleEvalModal;

/** `skill_timeout`: the payload you receive. */
export interface SkillTimeoutEvent {
  /** The skill. For a skill with `share` in G, the skill that it shares the cooldown with, for example `"quickpunch"` for `quickstab`, or `"use_hp"` for `regen_hp` (node/server_functions.js:3452-3455). */
  name: SkillName;
  /** The time until the skill is ready. From `consume_skill`, it includes `penalty`. The `attack_ms` form can be 0 or less: then the skill is ready now. */
  ms: Milliseconds;
  /** Only from `consume_skill`: the part of `ms` that comes from the `penalty_cd` condition, up to 10,000. Often `0`. */
  penalty?: Milliseconds;
  /** Only when the attack speed changed: `ms` is `attack_ms - (time since the last attack)` (node/server.js:1630-1634). */
  reason?: "attack_ms";
}

/** `start`: the payload you receive. */
export interface StartEvent extends Omit<Character, "code"> {
  /** A random string of 12 characters. The HTTP check-in of the official client sends it back. */
  ipass: string;
  /** The home server of the character, `player.p.home`: region plus server name, for example `"EUI"`. */
  home: string;
  /** The friend list of the account: the user ids of the friends (node/server.js:11632). */
  friends: string[];
  /** The cosmetics that the account owns: cosmetic name to count. */
  acx: Record<string, number>;
  /** A list of cosmetic names. The server only sets it to `[]` (node/server_functions.js:4448). The official client adds the free cosmetics of the class. */
  xcx: string[];
  /** `instance.info` of the instance of the character. Usually `{}`. A duel instance has `{seconds, active, A, B, id}` (node/server.js:12238-12246). The `tavern` has `{dice, num, seconds}`. A dream cave floor has `{zone}` (see Notes). */
  info: MapInfoDuel | NewMapTavernInfo | NewMapZoneInfo | Record<string, unknown>;
  /** `D.base_gold`: monster type to map name to the base gold of one kill (node/server_functions.js:231-232). */
  base_gold: Record<string, Record<string, number>>;
  /** The server event state `E`, the same object as the `server_info` payload. */
  s_info: ServerInfoState;
  /** Only while the server has a blessing: the character that paid for it. */
  blessed_by?: CharacterName;
  /** Only while the server has a blessing: the minutes that remain. */
  blessed_minutes?: number;
  /** When `auth` loaded code from a code slot: the source code text. It replaces the `code` flag of `player_to_client` (node/server.js:11937-11941). Otherwise it is that flag. */
  code?: boolean | string;
  /** Only with the code text: the code slot that the server found for `auth.code_slot`, as a string. */
  code_slot?: string;
  /** Only with the code text: the save count of that code slot. */
  code_version?: number;
  /** An `entities` payload with `type: "all"` for the start position (`send_all_xy(player, {raw: true})`). */
  entities: EntitiesFrame;
}

/** `tauri_auth`: the payload you receive. */
export interface TauriAuthEvent {
  /** `"persisted_steam_id"`: the account or character already had a Steam id, and the server did not check the ticket. `"steam_ticket_verified"`: Steam accepted the ticket. */
  status: "persisted_steam_id" | "steam_ticket_verified";
  /** The Steam id: 16 to 20 digits as a string (node/server_functions.js:873-877; adventure_functions.js:35 for a ticket). */
  pid: string;
  /** `true` when `auth` had a `ticket`. */
  ticket_received: boolean;
}

/** `tauri_auth_error`: the payload you receive. */
export interface TauriAuthErrorEvent {
  /** `"steam_auth_failed"`: Steam did not accept the ticket, or the check had an error. `"steam_link_failed"`: the server could not save the Steam id to the account and the character. */
  reason: "steam_auth_failed" | "steam_link_failed";
  /** The step that failed. `steam_auth_failed` always has `"verify_ticket"`. `steam_link_failed` has `"persist_saved_id"` (a Steam id that the account had) or `"persist_verified_ticket"` (a new Steam id from the ticket). */
  stage: "verify_ticket" | "persist_saved_id" | "persist_verified_ticket";
  /** `true` when `auth` had a `ticket`. */
  ticket_received: boolean;
}

/** `tavern`: the payload you receive. */
export type TavernEvent = TavernInfo | TavernDiceBet | TavernDiceWon | TavernDiceLost | TavernSlots | TavernWheel | TavernRefund | TavernRoulette;

/** `test`: the payload you receive. */
export interface TestEvent {
  /** The time of the server now: a `Date`, which arrives as an ISO 8601 string in UTC. */
  date: string;
}

/** `track`: the payload you receive. */
export type TrackEvent = TrackEntry[];

/** `tracker`: the payload you receive. */
export interface TrackerEvent {
  /** Monster type to the kills of this character (`player.p.stats.monsters`). */
  monsters: Record<string, number>;
  /** Monster type to a score correction (`player.p.stats.monsters_diff`). Each kill adds `score - 1` from `calculate_monster_score` (node/server.js:2662-2714), so the value can be negative and can have a fraction. The tracker count is `monsters + monsters_diff`. */
  monsters_diff: Record<string, number>;
  /** Drop table name to the exchanges of this character (`player.p.stats.exchanges`). For an item with levels (upgrade or compound), the name has the level as a suffix, for example `"armorbox0"`. */
  exchanges: Record<string, number>;
  /** Map name to the drop table of the map (`D.drops.maps`). It also has the keys `global` and `global_static`. */
  maps: Record<string, DropRow[]>;
  /** Table name to drop table: each exchange table (`G.items[name].e`), and each table that an `"open"` entry of any table in this payload names. Upgradable and compoundable items have one table for each level: `<name><level>`. */
  tables: Record<string, DropRow[]>;
  /** The best values of all characters of the account (`player.max_stats`). */
  max: TrackerMax;
  /** Monster type to the extra drops on the home server (`D.drops.monsters_home_server`). This is a drop table, not a kill count. */
  monsters_home_server: Record<string, DropRow[]>;
  /** Monster type to the drop table of the monster (`D.drops.monsters`), for every monster. */
  drops: Record<string, DropRow[]>;
  /** The same object as `monsters_home_server`. */
  drops_home: Record<string, DropRow[]>;
  /** The global drop table (`D.drops.maps.global`): every kill rolls it. Present when the table exists. The live `drops.js` has it. */
  global?: DropRow[];
  /** The second global table (`D.drops.maps.global_static`). Present when the table exists, even when it is empty. */
  global_static?: DropRow[];
}

/** `trade_history`: the payload you receive. */
export type TradeHistoryEvent = TradeHistoryEntry[];

/** `ui`: the payload you receive. */
export type UiEvent = UiNamed | UiBare | UiFromTo | UiThrow | UiFromTargets | UiBeaconOfResolve | UiArea | UiAbsorb | UiTargetId | UiGatherFail | UiGatherStart | UiGatherNone | UiMluckFind | UiNpcSell | UiNpcBuy | UiResale | UiTrade | UiSwap | UiItemSent | UiGoldSent | UiCxSent | UiResist | UiRestoreMp | UiMlevel | UiDisengage | UiMheal | UiSlots | UiWheel | UiCaveEnter;

/** `upgrade`: the payload you receive. */
export interface UpgradeEvent {
  /** The animation. `"exchange"` for the exchange NPC. `"poof"` for the statue in spookytown. `<token>s` (for example `"monstertokens"`) for a token exchange: always the token name plus `s`, also when the NPC has another name. */
  type: "upgrade" | "compound" | "exchange" | "poof" | string;
  /** `1` for a success, `0` for a failure. Only `upgrade` and `compound` send `0`. */
  success: 0 | 1;
}

/** `welcome`: the payload you receive. */
export interface WelcomeEvent {
  /** The region of the server, for example `"EU"`, `"US"` or `"ASIA"`. */
  region: string;
  /** The name of the server in its region, for example `"I"`, `"II"` or `"PVP"`. */
  name: string;
  /** `true` on a PvP server (`is_pvp`): a name that starts with `PVP` or `HARDCORE`, and the `TEST` and `DUNGEON` servers (node/server.js:367-418). */
  pvp: boolean;
  /** The game mode of the server. The server name selects it (node/server.js:367-410). */
  gameplay: "normal" | "hardcore" | "test" | "dungeon";
  /** `instance.info` of the first map. In practice it is always `{}`: the code reads `socket.first_map` before it sets it (node/server.js:4982-4985). The `start` entry lists the forms of `instance.info`. */
  info: EmptyObject;
  /** `G.version`, the version of the game data, for example `17478`. */
  version: number;
  /** The start position of the camera: the observer point of the server, or the position of the matched character. */
  x: number;
  /** The start position of the camera. The server adds 120 to the observer point. For a matched character it adds 120 only when the query has `desktop` (node/server.js:4987, 5003-5006). */
  y: number;
  /** The start map of the camera: the map of the matched character, or the observer map of the server. */
  map: MapName;
  /** The start instance of the camera. */
  in: InstanceName;
  /** The server event state `E`, the same object as the `server_info` payload. The page "Server events" lists its keys. */
  S: ServerInfoState;
  /** Only when the `secret` query parameter matches the secret of a character on this server. A character in a generated map matches only with `map_protocol=1`. */
  character?: WelcomeCharacter;
}

